WITH src AS (SELECT * FROM orders WHERE amount > 1300 AND customer_id IS NULL AND discount < 0.2), OrdersStats AS (SELECT CASE WHEN channel IN ('mobile', 'store') THEN 'core' ELSE 'other' END channel_group, ROUND((100 * SUM(CASE WHEN channel = 'store' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_store, MIN(discount) min_discount FROM src GROUP BY CASE WHEN channel IN ('mobile', 'store') THEN 'core' ELSE 'other' END) SELECT channel_group, min_discount FROM OrdersStats WHERE pct_store > 24;
